import re

def parse(lines):
    rx = re.compile(r'^\s+(?P<m>\S(?:.*?\S)?)\s{2,}(?:(?P<ops>[\d.]+) ops/sec\s+(?P<us>\d+) usecs/op|(?P<na>n/a\*?))\s*$')
    recs = []
    used = []
    skip = []
    sec = ''
    inpar = False
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if inpar:
            skip.append(i)
            if s.endswith(')') or s.endswith(').'):
                inpar = False
            continue
        if s.startswith('('):
            skip.append(i)
            if not (s.endswith(')') or s.endswith(').')):
                inpar = True
            continue
        m = rx.match(l)
        if m:
            if m.group('na'):
                ops = m.group('na')
                us = ''
            else:
                ops = float(m.group('ops'))
                us = int(m.group('us'))
            recs.append({'section': sec, 'method': m.group('m'), 'ops/sec': ops, 'usecs/op': us})
            used.append(i)
            continue
        if not l[0].isspace() and s.endswith(':'):
            sec = s[:-1]
        skip.append(i)
    blocks = []
    if recs:
        blocks.append({'name': 'tests', 'kind': 'table', 'lines': used, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
